#!/usr/bin/env python3
# Parse a Cobalt Strike beacon config blob (key\0 <u16 len> value records).
import struct
data = open("pid.4120.dmp", "rb").read()
i = 0
cfg = {}
while i < len(data):
    z = data.find(b"\x00", i)
    if z < 0 or z + 3 > len(data):
        break
    key = data[i:z]
    ln = struct.unpack("<H", data[z+1:z+3])[0]
    val = data[z+3:z+3+ln]
    if key and all(32 <= c < 127 for c in key) and ln < 200:
        try:
            cfg[key.decode()] = val.decode("latin-1")
        except Exception:
            pass
        i = z + 3 + ln
    else:
        i = z + 1
for k in ("BeaconType", "Port", "C2Server", "UserAgent", "SpawnTo", "Watermark"):
    if k in cfg:
        print("%-10s = %s" % (k, cfg[k]))
print("watermark (flag):", cfg.get("Watermark", "?"))
